// STEP 3 + 4 - the proper layout of a FUEL STATION and of an ELECTRIC CHARGE POINT as PURE NUMBERS (no three.js, no Rapier, no DOM), in the SITE FRAME.
// StationStructures.ts turns the parts into merged meshes, the same parts (those flagged `solid`) become Rapier cuboids (SignPhysics), sitePaint() is draped by
// StationStructures too, and scripts/station-structures-test.ts checks all of it headless. Step 4: the sites stand beside the main roads (RoadStationSites.ts, generated by
// scripts/gen-road-stations.ts); a site is a rectangle (hw, hd = half size along / across the road) and everything of a fuel station sits INSIDE it, everything of a charge point
// just OUTSIDE its stand-still rectangle.
//
// SITE FRAME ("local"): origin = centre of the lot, y = 0 just above the asphalt, the ROAD is always at local +z, local +x runs along the road. World = centre + R(yaw) * local
// (three.js rotation.y = yaw). The entry lane is at local x = -LANE.x (it goes -z, into the lot), the exit lane at +LANE.x (it goes +z, out to the road).
//
// FUEL STATION (32 x 26 m): canopy on 4 columns over 2 pump islands (2 pumps each, nozzle + hose + price display), a kiosk with glass windows and a door at the back,
//   3 underground-tank manhole covers, an air / water post, a big pylon sign facing the road, the entry / exit lanes with arrows + stop line, and the TANKER UNLOAD point
//   (a coupling post + a yellow hatched bay at the left wall; visual only - the unload logic still triggers anywhere in the lot rectangle).
// CHARGE POINT (8 x 4 m, or a 12 x 3.5 m bus bay): 2 or 3 charger posts + a solar canopy + a transformer and a battery cabinet, all BEHIND the stand-still rectangle, a blue
//   EV bay marking with a lightning-bolt logo, a small sign.
import type { SignSolid } from '../signs/SignSolids';

/** Entry lane centre (local x = -x, going into the lot) and exit lane centre (+x), half width of each lane. */
export const STATION_LANE = { x: 8, half: 2.5 } as const;

export type MatKey =
  | 'kerb' | 'roof' | 'fascia' | 'col' | 'pump' | 'pumpTop' | 'charger' | 'screen' | 'yellow' | 'white' | 'dark'
  | 'building' | 'glass' | 'door' | 'light' | 'iron' | 'solar' | 'silver' | 'cab' | 'cabW';
export type TexKey = 'pylon' | 'shop' | 'unload' | 'cp';

/** A box (or an upright cylinder, w = diameter) in the station frame: centre x y z, size w (x) h (y) d (z); rx = tilt about the x axis (rad). */
export interface Part { m: MatKey; x: number; y: number; z: number; w: number; h: number; d: number; rx?: number; cyl?: boolean; solid?: boolean }
/** A textured board: faces +z when ry = 0, -z when ry = PI, +x when ry = PI/2. */
export interface PlanePart { t: TexKey; x: number; y: number; z: number; w: number; h: number; ry: number }
export interface Layout { parts: Part[]; planes: PlanePart[] }

/** Half size of a site (m): hw along the road, hd across it. */
export interface Dims { hw: number; hd: number }

/** The tanker unload bay (yellow hatched box + the coupling post beside it), local frame, left wall of a small station. */
export const UNLOAD_BAY = { x0: -14.2, x1: -11.2, z0: -9.0, z1: -1.5, postX: -15.2, postZ: -5.2 } as const;
/** Pump positions (local): islands at z = +-3, pumps at x = +-1.8; the corridor between the islands (z = 0) is the drive-through. */
export const ISLAND_Z = [-3, 3] as const;
export const PUMP_X = [-1.8, 1.8] as const;

function slabY(z: number, zc: number, rx: number, y0: number): number {
  return y0 - (z - zc) * Math.sin(rx);
}

// ---------------------------------------------------------------------------------------------------------------------------------
// FUEL STATION
// ---------------------------------------------------------------------------------------------------------------------------------
export function fuelLayout(d: Dims): Layout {
  const hd = d.hd;
  const P: Part[] = [];
  const T: PlanePart[] = [];
  const box = (m: MatKey, x: number, y: number, z: number, w: number, h: number, d: number, solid = false): void => void P.push({ m, x, y, z, w, h, d, solid });

  const pump = (x: number, z: number): void => {
    box('pump', x, 1.1, z, 0.7, 1.8, 0.45, true);
    box('pumpTop', x, 2.1, z, 0.78, 0.2, 0.52);
    for (const sz of [-1, 1]) box('screen', x, 1.65, z + sz * 0.24, 0.5, 0.28, 0.03); // price display, on both faces (the lanes are on both sides)
    for (const sx of [-1, 1]) {
      box('dark', x + sx * 0.41, 1.15, z, 0.1, 0.36, 0.14); // nozzle holster
      box('yellow', x + sx * 0.46, 1.36, z, 0.07, 0.22, 0.1); // the nozzle
      box('dark', x + sx * 0.45, 0.6, z, 0.04, 0.7, 0.04); // hose
    }
  };

  // two pump islands under one canopy on 4 columns (the columns stand ON the island ends, so the lanes stay free)
  for (const iz of ISLAND_Z) {
    box('kerb', 0, 0.1, iz, 9.2, 0.2, 1.4);
    for (const px of PUMP_X) pump(px, iz);
    for (const cx of [-3.9, 3.9]) box('col', cx, 2.525, iz, 0.4, 5.05, 0.4, true);
    box('light', 0, 4.97, iz, 7.4, 0.06, 0.5);
  }
  box('fascia', 0, 5.3, 0, 18.2, 0.55, 15.2);
  box('roof', 0, 5.52, 0, 17.8, 0.25, 14.8);

  // kiosk / shop at the back (right), glass windows + door facing the pumps
  const kx = 9.5, kz = -hd + 2.6;
  box('building', kx, 1.7, kz, 10.8, 3.4, 4.0, true);
  box('roof', kx, 3.52, kz + 0.4, 11.6, 0.25, 4.8);
  box('glass', 6.6, 1.7, kz + 2.0 + 0.03, 3.0, 1.5, 0.06);
  box('glass', 12.4, 1.7, kz + 2.0 + 0.03, 3.0, 1.5, 0.06);
  box('door', kx, 1.15, kz + 2.0 + 0.04, 1.4, 2.3, 0.08);
  T.push({ t: 'shop', x: kx, y: 2.85, z: kz + 2.0 + 0.05, w: 3.0, h: 0.8, ry: 0 });

  // underground tank manhole covers (flat, on the ground), left-back
  for (const mx of [-8, -5, -2]) P.push({ m: 'iron', x: mx, y: 0, z: -hd + 3.6, w: 0.9, h: 0.05, d: 0.9, cyl: true });

  // air / water post (right wall)
  box('cab', 13.4, 0.65, -5.2, 0.5, 1.3, 0.4, true);
  box('charger', 13.4, 1.42, -5.2, 0.56, 0.25, 0.46);
  box('dark', 13.4, 0.5, -4.95, 0.05, 0.5, 0.05);

  // TANKER UNLOAD point: coupling post at the left wall, a board facing the bay, a silver coupling on the bay side
  const ux = UNLOAD_BAY.postX, uz = UNLOAD_BAY.postZ;
  box('yellow', ux, 1.0, uz, 0.35, 2.0, 0.35, true);
  box('dark', ux, 2.05, uz, 0.4, 0.1, 0.4);
  box('silver', ux + 0.28, 0.7, uz, 0.22, 0.25, 0.25);
  box('dark', ux + 0.45, 0.25, uz, 0.3, 0.06, 0.06);
  T.push({ t: 'unload', x: ux + 0.19, y: 1.55, z: uz, w: 1.5, h: 0.5, ry: Math.PI / 2 });

  // pylon sign at the road edge, between the two lanes, both faces (the road + the lot)
  const pz = hd - 1.4;
  box('col', 0, 4.7, pz, 0.6, 9.4, 0.6, true);
  box('fascia', 0, 6.6, pz, 3.8, 5.4, 0.35, true);
  T.push({ t: 'pylon', x: 0, y: 6.6, z: pz + 0.19, w: 3.6, h: 5.2, ry: 0 });
  T.push({ t: 'pylon', x: 0, y: 6.6, z: pz - 0.19, w: 3.6, h: 5.2, ry: Math.PI });
  return { parts: P, planes: T };
}

// ---------------------------------------------------------------------------------------------------------------------------------
// ELECTRIC CHARGE POINT
// ---------------------------------------------------------------------------------------------------------------------------------
export function chargeLayout(d: Dims): Layout {
  const hw = d.hw, hd = d.hd;
  const P: Part[] = [];
  const T: PlanePart[] = [];
  const box = (m: MatKey, x: number, y: number, z: number, w: number, h: number, d: number, solid = false): void => void P.push({ m, x, y, z, w, h, d, solid });
  const pz = -hd - 0.3; // charger posts stand just BEHIND the stand-still rectangle (the vehicle parks along it)

  const n = hw > 4.5 ? 3 : 2;
  const xs = n === 3 ? [-hw * 0.66, 0, hw * 0.66] : [-hw * 0.5, hw * 0.5];
  for (const x of xs) {
    box('kerb', x, 0.07, pz, 0.9, 0.14, 0.7);
    box('charger', x, 0.14 + 0.85, pz, 0.5, 1.7, 0.4, true);
    box('screen', x, 1.5, pz + 0.21, 0.36, 0.3, 0.03); // screen on the bay side
    box('yellow', x + 0.3, 1.1, pz + 0.05, 0.08, 0.45, 0.1); // cable holder
    box('dark', x + 0.3, 0.75, pz + 0.1, 0.12, 0.28, 0.1); // connector
    box('dark', x + 0.3, 0.45, pz + 0.05, 0.04, 0.5, 0.04); // cable
  }
  // solar canopy: tilted panel slab on two end columns (behind the rectangle), the front edge high enough for a bus (>= 4.1 m)
  const rx = 0.17, zc = -0.2, y0 = 4.65, L = 2 * hd + 1.2;
  for (const sx of [-1, 1]) box('col', sx * (hw + 0.25), 2.5, pz, 0.35, 5.0, 0.35, true);
  P.push({ m: 'solar', x: 0, y: y0, z: zc, w: 2 * hw + 0.8, h: 0.12, d: L, rx });
  P.push({ m: 'silver', x: 0, y: y0 - 0.09, z: zc, w: 2 * hw + 0.9, h: 0.08, d: L + 0.1, rx });
  box('light', 0, slabY(hd - 0.2, zc, rx, y0) - 0.14, hd - 0.2, Math.max(1.5, 2 * hw - 0.8), 0.06, 0.25);
  // transformer + battery cabinet: behind the posts
  box('cab', -hw * 0.4, 0.85, -hd - 1.7, 1.5, 1.7, 1.0, true);
  box('cabW', hw * 0.4, 0.95, -hd - 1.7, 1.3, 1.9, 0.9, true);
  T.push({ t: 'cp', x: 0, y: slabY(hd + 0.4, zc, rx, y0) + 0.45, z: hd + 0.45, w: Math.min(3.4, 2 * hw), h: 0.9, ry: 0 });
  return { parts: P, planes: T };
}

/** The solid parts as Rapier cuboids in the station frame (a little fatter than the visible part, so a car does not slip through a gap that looks closed). */
export function solidsOf(layout: Layout): SignSolid[] {
  const out: SignSolid[] = [];
  for (const p of layout.parts) {
    if (!p.solid) continue;
    out.push({ k: 0, cx: p.x, cy: p.y, cz: p.z, hx: p.w / 2 + 0.04, hy: p.h / 2, hz: p.d / 2 + 0.04 });
  }
  return out;
}

/** Footprint of a solid in the site frame: [x0, x1, z0, z1]. */
export function solidFootprint(s: SignSolid): [number, number, number, number] {
  return [s.cx - s.hx, s.cx + s.hx, s.cz - s.hz, s.cz + s.hz];
}

// ---------------------------------------------------------------------------------------------------------------------------------
// GROUND: asphalt + paint, in the site frame (StationStructures drapes it over the ground)
// ---------------------------------------------------------------------------------------------------------------------------------
/** [x0, x1, z0, z1] in the site frame. */
export type LRect = readonly [number, number, number, number];
/** A painted line of width w from (x, z) a to b. */
export interface LSeg { a: readonly [number, number]; b: readonly [number, number]; w: number }
export interface SitePaint { asphalt: LRect[]; white: LRect[]; whiteLines: LSeg[]; yellow: LRect[]; yellowLines: LSeg[]; blue: LRect[]; blueLines: LSeg[] }

/** The paved ground and the paint of a site. `gap` = the driveway length between the lot edge and the road shoulder (it runs 0.5 m into the shoulder). */
export function sitePaint(fuel: boolean, d: Dims, gap: number): SitePaint {
  const out: SitePaint = { asphalt: [], white: [], whiteLines: [], yellow: [], yellowLines: [], blue: [], blueLines: [] };
  const hw = d.hw, hd = d.hd, W = 0.14, drive = gap + 0.5;
  out.asphalt.push([-hw, hw, -hd, hd]);
  if (fuel) {
    for (const cx of [-STATION_LANE.x, STATION_LANE.x]) out.asphalt.push([cx - STATION_LANE.half, cx + STATION_LANE.half, hd, hd + drive]);
    const line = (list: LSeg[], ax: number, az: number, bx: number, bz: number, w: number): void => void list.push({ a: [ax, az], b: [bx, bz], w });
    const arrow = (x: number, z: number, dx: number, dz: number): void => {
      line(out.whiteLines, x - dx * 1.2, z - dz * 1.2, x + dx * 0.7, z + dz * 0.7, 0.28);
      const tx = x + dx * 1.5, tz = z + dz * 1.5, px = -dz, pz = dx;
      for (const sg of [-1, 1]) line(out.whiteLines, tx, tz, tx - dx * 0.9 + px * 0.6 * sg, tz - dz * 0.9 + pz * 0.6 * sg, 0.28);
    };
    // dashed lane edges: entry lane (x = -LANE.x) and exit lane (x = +LANE.x), from the road edge to the island zone
    for (const cx of [-STATION_LANE.x, STATION_LANE.x]) {
      for (const ex of [-STATION_LANE.half, STATION_LANE.half]) {
        for (let z = hd - 0.6; z > 5.2; z -= 3) out.white.push([cx + ex - W / 2, cx + ex + W / 2, z - 1.6, z]);
      }
    }
    arrow(-STATION_LANE.x, hd - 4.0, 0, -1); // entry: into the lot
    arrow(STATION_LANE.x, hd - 4.0, 0, 1); // exit: out to the road
    arrow(0, 0, 1, 0); // drive-through corridor between the islands
    out.white.push([STATION_LANE.x - STATION_LANE.half, STATION_LANE.x + STATION_LANE.half, hd - 1.0, hd - 0.6]); // stop line on the exit lane
    // tanker unload bay: yellow outline + hatch
    const b = UNLOAD_BAY, yw = 0.12;
    out.yellow.push([b.x0, b.x1, b.z0, b.z0 + yw], [b.x0, b.x1, b.z1 - yw, b.z1], [b.x0, b.x0 + yw, b.z0, b.z1], [b.x1 - yw, b.x1, b.z0, b.z1]);
    for (const z0 of [-9.0, -6.0, -4.5]) line(out.yellowLines, b.x0, z0, b.x1, z0 + 3.0, 0.14);
  } else {
    out.asphalt.push([-hw, hw, hd, hd + drive]); // the whole width: a car drives straight into the bay from the road
    // white bay outline + a blue strip along the posts
    out.white.push([-hw + 0.1, hw - 0.1, -hd + 0.1, -hd + 0.1 + W], [-hw + 0.1, hw - 0.1, hd - 0.1 - W, hd - 0.1], [-hw + 0.1, -hw + 0.1 + W, -hd + 0.1, hd - 0.1], [hw - 0.1 - W, hw - 0.1, -hd + 0.1, hd - 0.1]);
    out.blue.push([-hw + 0.3, hw - 0.3, -hd + 0.3, -hd + 0.65]);
    // EV logo: a lightning bolt (one per 6 m of bay)
    const k = Math.max(1, Math.round(hw / 3));
    for (let i = 0; i < k; i++) {
      const cx = k === 1 ? 0 : -hw + (2 * hw * (i + 0.5)) / k, s = Math.min(1, hd * 0.5);
      out.blueLines.push({ a: [cx + 0.35 * s, 0.9 * s], b: [cx - 0.3 * s, -0.05 * s], w: 0.2 }, { a: [cx - 0.3 * s, -0.05 * s], b: [cx + 0.3 * s, -0.05 * s], w: 0.2 }, { a: [cx + 0.3 * s, -0.05 * s], b: [cx - 0.35 * s, -0.95 * s], w: 0.2 });
    }
  }
  return out;
}
